mapper.select:
SELECT id, quiz_id, concept_id, question, choices, answer_index, explanation
FROM quiz_questions WHERE quiz_id = #{quizId}
ORDER BY id

SELECT id, quiz_id, user_id, score, total, created_at
FROM quiz_attempts
WHERE quiz_id = #{quizId} AND user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT id, quiz_id, user_id, score, total, created_at
FROM quiz_attempts
WHERE id = #{attemptId} AND quiz_id = #{quizId} AND user_id = #{userId}

SELECT question_id, selected_index, is_correct
FROM quiz_answers WHERE attempt_id = #{attemptId}
ORDER BY question_id
